#include <stdio.h>
#include <string.h>

#define MAX_N 100000
#define MAX_STONES 100000

int grundy[MAX_STONES + 1]; 

int main() {
    int N, A, B;
    scanf("%d %d %d", &N, &A, &B);

    int stones[N];
    int max_stones = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &stones[i]);
        if (stones[i] > max_stones) max_stones = stones[i];
    }

    // Precompute Grundy numbers up to max_stones
    grundy[0] = 0;
    for (int i = 1; i <= max_stones; i++) {
        int seen[3] = {0}; // Only 0,1,2 possible
        for (int take = 1; take <= A && take <= i; take++) {
            seen[grundy[i - take]] = 1;
        }
        for (int g = 0; g < 3; g++) {
            if (!seen[g]) {
                grundy[i] = g;
                break;
            }
        }
    }

    int xor_sum = 0;
    for (int i = 0; i < N; i++) {
        xor_sum ^= grundy[stones[i]];
    }

    if (xor_sum != 0)
        printf("Hanako\n");
    else
        printf("Jiro\n");

    return 0;
}

